mapper.select:
SELECT


FROM SysAppDevice a WHERE 1 = 1

    AND a.accountId = #{accountId}


    AND a.deviceType = #{deviceType}


    AND a.deviceName = #{deviceName}


    AND a.deviceNumber = #{deviceNumber}


    AND a.ipAddress = #{ipAddress}


    AND a.appVersion = #{appVersion}


    AND a.buildVersion = #{buildVersion}


    AND a.lastLoginDate = #{lastLoginDate}


    AND a.createDate = #{createDate}


    AND a.remark = #{remark}
